import{_ as e,o as t,c as i,ai as l}from"./chunks/framework.ampVZV4B.js";const u=JSON.parse('{"title":"7. 并发：原子、Lua、库存、限流","description":"","frontmatter":{},"headers":[],"relativePath":"redis/07-concurrency.md","filePath":"redis/07-concurrency.md"}'),s={name:"redis/07-concurrency.md"};function r(d,a,n,o,c,p){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="_7-并发-原子、lua、库存、限流" tabindex="-1">7. 并发：原子、Lua、库存、限流 <a class="header-anchor" href="#_7-并发-原子、lua、库存、限流" aria-label="Permalink to “7. 并发：原子、Lua、库存、限流”">​</a></h1><p>目标：讲清 Redis 侧「并发安全」靠什么——单线程命令、Lua 脚本、正确的锁与限流，而不是在应用里瞎加锁。</p><p>相关：<a href="./distributed-lock.html">分布式锁</a> · <a href="./data-types.html">数据结构</a></p><hr><h2 id="原子操作" tabindex="-1">原子操作 <a class="header-anchor" href="#原子操作" aria-label="Permalink to “原子操作”">​</a></h2><p>单条 Redis 命令在服务端执行期间不会被其它命令打断（主线程串行执行命令）。</p><p>常用：</p><ul><li><code>INCR</code> / <code>DECR</code> / <code>INCRBY</code>：计数、库存粗扣</li><li><code>SET key value NX PX</code>：加锁</li><li><code>SETNX</code> 已不推荐单独用（易忘过期）</li></ul><p><strong>边界：</strong> 多条命令默认<strong>不原子</strong>。要组合逻辑 → <strong>Lua</strong> 或 Redisson 等封装。</p><hr><h2 id="lua" tabindex="-1">Lua <a class="header-anchor" href="#lua" aria-label="Permalink to “Lua”">​</a></h2><p>Redis 执行 Lua 期间，其它命令插不进来，适合：</p><ul><li>校验 + 删除锁（防误删）</li><li>扣库存：读余量 → 判断 → 扣减</li><li>限流窗口内计数 + 过期</li></ul><p>原则：</p><ul><li>脚本要短、确定性、避免大循环</li><li>尽量用 <code>EVALSHA</code> 减网络传脚本开销</li><li>不要在 Lua 里做外部 IO</li></ul><hr><h2 id="库存扣减" tabindex="-1">库存扣减 <a class="header-anchor" href="#库存扣减" aria-label="Permalink to “库存扣减”">​</a></h2><p><strong>简单版（面试常答）：</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Lua / 原子：</span></span>
<span class="line"><span>  若 stock &lt;= 0 → 失败</span></span>
<span class="line"><span>  否则 DECR → 成功</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>注意：</p><ul><li>Redis 扣成功 ≠ 订单落库成功 → 要有<strong>对账 / 回滚库存 / 预扣+确认</strong></li><li>超卖防护在 Redis；资金与订单权威仍在 DB 事务</li></ul><p><strong>优化：</strong> 热点 SKU 分桶库存（<code>sku:1001:bucket:0..N</code>）降低单 Key 竞争；最终汇总。</p><hr><h2 id="限流" tabindex="-1">限流 <a class="header-anchor" href="#限流" aria-label="Permalink to “限流”">​</a></h2><p>常见：</p><table tabindex="0"><thead><tr><th>方式</th><th>思路</th><th>场景</th></tr></thead><tbody><tr><td>固定窗口计数</td><td><code>INCR</code> + 首次数 <code>EXPIRE</code></td><td>简单接口限流</td></tr><tr><td>滑动窗口</td><td>ZSet 时间戳成员</td><td>更平滑</td></tr><tr><td>令牌桶 / 漏桶</td><td>应用或网关实现，Redis 存状态</td><td>网关层更常见</td></tr></tbody></table><p>口述：</p><blockquote><p>接口限流我用 Redis 做分布式计数，Key 带用户或 IP + 接口 + 窗口；超阈值直接拒绝。要平滑再用滑动窗口；网关层限流和业务限流分层。</p></blockquote><hr><h2 id="核心优化" tabindex="-1">核心优化 <a class="header-anchor" href="#核心优化" aria-label="Permalink to “核心优化”">​</a></h2><ol><li>多步逻辑 → Lua 或成熟组件，忌客户端「先读后写」无锁</li><li>库存与订单状态机分开设计，避免「只信 Redis」</li><li>限流 Key 必须带维度与窗口，并设过期防泄漏</li><li>压测热 Key 限流/库存，必要时分片</li></ol><p>下一步：<a href="./transaction-pubsub.html">消息</a> · <a href="./10-practice.html">实战</a></p>`,32)])])}const b=e(s,[["render",r]]);export{u as __pageData,b as default};
